"""B07 — single source of truth registry.

Every governance document must be registered with an owner, the validator that
enforces it and the files it generates. Three properties follow, and all three
are checked:

* no governance file is unowned or unvalidated;
* no generated file has two generators, and no generated file is itself
  treated as a source of truth (that would make it editable by hand);
* every generated file carries the do-not-edit banner.
"""
from __future__ import annotations

from pathlib import Path
from typing import Any

from . import registry as validator_registry
from .errors import BudgetExceeded, Problem
from .repo import Budget, load_json
from .structs import BATCH_ID, SEMVER, expect

PATH = Path("governance/ssot-registry.json")
GOVERNANCE_DIR = Path("governance")


# Registered automatically: tools/paygov/registry.py discovers every module in
# this package that declares VALIDATOR. Adding a batch means adding a module,
# not editing a shared file that every earlier batch is pinned to.
VALIDATOR = ("ssot", "B07")

def validate(root: Path, budget: Budget | None = None) -> list[Problem]:
    budget = budget or Budget().start()
    where = str(PATH)
    try:
        doc: Any = load_json(root / PATH, budget)
    except BudgetExceeded:
        raise
    except Exception as exc:
        return [Problem("SSOT_UNREADABLE", where, str(exc), "NN-12")]

    problems: list[Problem] = []
    problems += expect(bool(SEMVER.match(str(doc.get("schema_version", "")))),
                       "SSOT_VERSION", where, "schema_version must be semantic version", "NN-12")

    sources = doc.get("sources")
    if not isinstance(sources, list) or not sources:
        return problems + [Problem("SSOT_SHAPE", where, "'sources' must be a non-empty array",
                                   "NN-12")]

    validator_registry.load_all()
    known_validators = set(validator_registry.names())

    registered_paths: set[str] = set()
    generated_by: dict[str, str] = {}
    banner = doc.get("generated_banner", "GENERATED FILE")

    for source in sources:
        sid = source.get("id", "?")
        scope = f"{where}#{sid}"
        rel = source.get("path", "")
        registered_paths.add(rel)
        problems += expect((root / rel).is_file(), "SSOT_MISSING", scope,
                           f"registered source '{rel}' does not exist", "NN-12")
        problems += expect(len(str(source.get("owner", "")).strip()) >= 4, "SSOT_OWNER", scope,
                           "every source of truth needs a named owner", "NN-11")
        batch = source.get("batch", "")
        problems += expect(bool(BATCH_ID.match(str(batch))), "SSOT_BATCH", scope,
                           f"'{batch}' is not a batch id", "NN-12")
        validator = source.get("validator")
        problems += expect(validator in known_validators, "SSOT_VALIDATOR", scope,
                           f"validator '{validator}' is not registered; an unvalidated source of "
                           f"truth is a document, not a control", "NN-12")
        if validator in known_validators:
            # This registry is no longer pinned to B07's artefact digest — it
            # grows by construction, once per batch, so pinning it meant B07's
            # evidence expired every batch and cascaded a full re-baseline.
            # What replaces the pin is this: an entry cannot lie about which
            # batch owns it, because the owning batch is whatever the validator
            # module itself declares.
            owner_batch = validator_registry.batch_of(validator)
            problems += expect(batch == owner_batch, "SSOT_BATCH_MISMATCH", scope,
                               f"'{sid}' claims batch '{batch}' but its validator "
                               f"'{validator}' is declared by {owner_batch}", "NN-12")
        for generated in source.get("generates", []):
            if generated in generated_by:
                problems.append(Problem("SSOT_DOUBLE_GENERATOR", scope,
                                        f"'{generated}' is also generated by "
                                        f"'{generated_by[generated]}'", "NN-12"))
            generated_by[generated] = sid
            path = root / generated
            if not path.is_file():
                problems.append(Problem("SSOT_GENERATED_MISSING", scope,
                                        f"generated file '{generated}' does not exist", "NN-12"))
                continue
            head = path.read_text(encoding="utf-8")[:400]
            problems += expect(banner in head, "SSOT_BANNER", scope,
                               f"'{generated}' does not carry the '{banner}' banner", "NN-12")

    for path in sorted((root / GOVERNANCE_DIR).glob("*.json")):
        rel = path.relative_to(root).as_posix()
        problems += expect(rel in registered_paths, "SSOT_UNREGISTERED", rel,
                           "governance file is not registered in the SSOT registry", "NN-12")

    for generated in sorted(generated_by):
        problems += expect(generated not in registered_paths, "SSOT_GENERATED_IS_SOURCE",
                           generated,
                           "a generated file may not also be registered as a source of truth",
                           "NN-12")
    return problems
